          "content": "سجل بسيط يومي يوفر عليك خسائر كبيرة لاحقاً:\n• عدد النفوق اليومي وسببه المحتمل\n• استهلاك العلف والماء الفعلي\n• أي دواء أو تحصين أُعطي وتاريخه\n• الوزن الأسبوعي لعينة من القطيع\n• أي ملاحظة غير طبيعية\n\nالفائدة: مقارنة الأداء بمرور الوقت تكشف مشاكل تدريجية (تغذية، بيئة) لا تظهر في يوم واحد، وتساعدك تحسب فترة السحب الآمنة لأي دواء بدقة"
