        {
          "title": "أسرار التزاوج الناجح",
          "content": "معلومات لا يعرفها كثير من مربي الأرانب:\n\nمتى الأنثى مستعدة للتزاوج؟\n• الأرنبة لا تملك دورة شهرية محددة\n• تبيض عند التزاوج (تبويض مستحث)\n• لون فرج الأنثى يدل على حالتها:\n  - وردي فاتح: غير مستعدة\n  - أحمر زاهي: في أوج الاستعداد ✅ الآن!\n  - بنفسجي داكن: تجاوزت الذروة\n\nطريقة التزاوج الصحيحة:\n1. انقل الأنثى لقفص الذكر (ليس العكس)\n2. راقب: الذكر يتزاوج خلال دقائق\n3. بعد التزاوج: يسقط الذكر على جانبه ويصرخ = تزاوج ناجح\n4. أعد الأنثى لقفصها فوراً\n5. كرر بعد 6-8 ساعات للتأكيد\n\nأسباب رفض التزاوج:\n• حر شديد (فوق 30°م) = راحة الأرانب شبه جنسية\n• أنثى سمينة جداً = لا تتزاوج\n• ذكر مريض أو كسول\n• أنثى حامل (ترفض دائماً)\n\nالحل في الصيف:\n• طعّم فجراً (أبرد وقت)\n• ضع مياه باردة جداً قبل التزاوج\n• أضف فيتامين E قبل موسم التزاوج بأسبوع"
        },
        {
          "title": "إدارة الأم قبل وبعد الولادة",
          "content": "الأسبوع الأخير من الحمل (يوم 25-31):\n\nعلامات قرب الولادة:\n• الأم تنتف شعرها وتبني عشاً\n• تصبح عدوانية وتهرب من يدك\n• تقل شهيتها\n\nالعش المثالي:\n• صندوق خشبي: 30 × 25 × 20 سم\n• ضع قش ناعم + شعر الأم\n• درجة الحرارة داخله: 30-35°م\n\nلحظة الولادة:\n• اترك الأم وحدها تماماً\n• لا تفتح الصندوق أول 24 ساعة\n• الولادة تحدث ليلاً في الغالب\n\nبعد الولادة — أول 24 ساعة:\n• تأكد من وجود حليب (اضغط لطيفاً على الثدي)\n• الصغار تتحرك تحت الشعر = بخير\n• الصغار باردة وصامتة = مشكلة\n\nإذا الأم لم ترضع:\n• امسكها بلطف وضع الصغار على بطنها\n• أحياناً الأمهات في أول مرة تحتاج مساعدة\n• كرر مرتين يومياً لمدة 3 أيام\n\nالفطام:\n• عمر 28-35 يوم (3-5 أسابيع)\n• الفطام المبكر = ضعف جهاز هضمي\n• الفطام المتأخر = إرهاق الأم"
        }
