          "content": "• بيبدأ البيض في عمر 6-7 أسابيع وبيوصل الذروة تقريباً بين 10-14 أسبوع (حسب الإدارة)، والعمر الاقتصادي للإنتاج حوالي سنة\n• إنتاج جيد: 250-300 بيضة للطائر في السنة، ووزن البيضة حوالي 10-12 جم\n• المساحة: حوالي 150-200 سم² للطائر البياض في القفص\n• العلف: بروتين حوالي 20% وكالسيوم حوالي 2.5-3% (راجع برنامج التغذية)، واستهلاك حوالي 25-30 جم/طائر/يوم\n• الإضاءة: 16-17 ساعة ثابتة بدون تذبذب (راجع برنامج الإضاءة)\n• جمع البيض: مرتين يومياً على الأقل، وتخزينه في مكان بارد وجاف\n• سجّل يومياً: عدد البيض والنفوق واستهلاك العلف، واحسب نسبة الإنتاج (HDP)"
