          "title": "أنظمة التزاوج بعد الولادة",
          "content": "اختيار النظام بيحدد عدد البطون في السنة وصحة الأم:\n\n1) النظام المكثف (Intensive): تزاوج الأنثى بعد الولادة بيوم لـ 3 أيام تقريباً\n• أعلى إنتاجية لكنه بيرهق الأم جداً، ومحتاج تغذية ممتازة وإدارة قوية وسلالة مناسبة\n\n2) شبه المكثف (Semi-intensive): تزاوج بعد الولادة بحوالي 11-14 يوم (دورة حوالي 42 يوم)\n• توازن كويس بين الإنتاج وصحة الأم، وهو الأكتر استخداماً في المزارع التجارية\n\n3) الممتد (Extensive): تزاوج بعد الفطام (28-35 يوم) أو أكتر\n• إجهاد أقل وعدد بطون أقل في السنة، مناسب للمبتدئين\n\nالقاعدة: ابدأ بنظام شبه مكثف أو ممتد، ومتدفعش الأنثى لنظام أكثف إلا لو حالتها الجسدية وتغذيتها وصحتها ممتازة."
