          "title": "إزاي تقرأ بطاقة العلف",
          "content": "أي علف جيد لازم عليه بطاقة بيانات (Feed Tag) فيها التحليل المضمون. أهم البنود:\n• البروتين الخام (CP) %: حسب المرحلة (راجع برامج التغذية)\n• الطاقة الممثلة (ME): كيلو كالوري/كجم\n• الكالسيوم والفوسفور المتاح: مهم للقشرة والعظام\n• الأحماض الأمينية: الميثيونين واللايسين (أهم اتنين)\n• الألياف الخام: كل ما زادت قلّت الطاقة\n• الرطوبة: لو عالية بيحصل تعفن (الحد الأقصى المعتاد حوالي 12-13%)\n• الرماد والملح: بيكشف الرمل والأملاح الزيادة\n• الإضافات: مضادات كوكسيديا، إنزيمات، مضاد سموم (مع فترة سحب لو موجودة)\n• تاريخ التصنيع ومدة الصلاحية ورقم التشغيلة\n\nنصايح:\n• البطاقة مجرد وعد — الاختبار الحقيقي بعينة معملية (بروتين، رطوبة، أفلاتوكسين)\n• لو الأداء نزل بعد شحنة جديدة، ابعت عينة محفوظة من الشحنة للمعمل\n• احتفظ بعينة حوالي 1 كجم من كل شحنة في كيس نظيف جاف لحد نهاية الدورة"
