          "content": "تكلفة العلف الحقيقية بتتحسب على الكيلو المنتج، مش على كيلو العلف:\n\nتكلفة العلف لكل كجم لحم = سعر كجم العلف × FCR\n\nمثال مقارنة (أرقام افتراضية):\n• علف A: 18 جنيه/كجم، FCR 1.80 → 32.40 جنيه لكل كجم لحم\n• علف B: 17.50 جنيه/كجم، FCR 1.90 → 33.25 جنيه لكل كجم لحم\n\nرغم إن B أرخص بنص جنيه في الكيلو، تكلفته أعلى بـ 0.85 جنيه على كل كجم لحم. في دورة 10,000 كجم لحم الفرق = 8,500 جنيه.\n\nللبياض:\nكجم العلف لكل دستة = (استهلاك الطائر اليومي بالكجم × 12) ÷ (عدد البيض اليومي للطائر)\nمثال: 115 جم علف وإنتاج 90% → (0.115 × 12) ÷ 0.9 ≈ 1.53 كجم علف للدستة\nبسعر 18 جنيه/كجم → حوالي 27.6 جنيه علف لكل دستة\n\nالقاعدة: قارن بتكلفة العلف لكل وحدة منتجة (كجم لحم أو دستة بيض)، مش بالسعر على الورق."
