          "title": "ليه التشريح أدق من الأعراض",
          "content": "الأعراض الظاهرية بتتشابه بين أمراض كتير (خمول، انتفاش، إسهال)، لكن الآفات الداخلية بتضيّق الاحتمالات بشكل كبير. التشريح بياخد دقايق للطائر وبيوفر أيام من العلاج الغلط.\n\nقواعد اختيار الطيور:\n• شرّح طيور نافقة حديثاً (أقل من ساعتين في الحر) أو اذبح طائراً مريضاً بدل ما تستنى نفوقه — الجثة بتتحلل بسرعة وبتخفي الآفات\n• شرّح 3-5 طيور على الأقل من حالات مختلفة، مش طائر واحد\n• متشرّحش جثة اتجمدت أو اتحطت في مياه\n\nالأدوات: مقص تشريح، ملقط، سكين حاد، قفازات، مطهر، أكياس وعلب عينات نظيفة، وفورمالين 10% للعينات النسيجية.\n\nالسلامة:\n• التشريح بيعرّضك لأمراض بتنتقل للإنسان (زي السالمونيلا وإنفلونزا الطيور) — البس قفازات وكمامة، واغسل إيدك وأدواتك، واتخلص من الجثث بالدفن العميق أو الحرق\n• لو الاشتباه إنفلونزا طيور (نفوق جماعي مفاجئ + تورم وزرقان في الرأس والعرف) متشرّحش — بلّغ الجهات البيطرية فوراً"
