        {
          "title": "دلالات الآفات الشائعة — مؤشر مش حكم نهائي",
          "content": "• أكياس هوائية معتمة مع إفراز جبني أصفر = ميكوبلازما و/أو إشريكية (CRD)\n• طبقة ليفية بيضاء على الكبد والقلب = إشريكية غالباً\n• نزيف نقطي عند فتحات غدد المعدة الغدية = يشتبه نيوكاسل أو إنفلونزا (محتاج تأكيد معملي)\n• كيس فابريشيوس متضخم ومنزوف في عمر 3-6 أسابيع ثم يضمر = جمبورو\n• نزيف في عضلات الفخذ والصدر مع ضمور الكيس = جمبورو أو سموم فطرية\n• أعورين متضخمين مليانين دم = كوكسيديا الأعورين (E. tenella)\n• أمعاء دقيقة مغطاة بغشاء متقرح خشن (يشبه المنشفة التركية) = التهاب الأمعاء الناخر\n• أعور ملتهب مع كبد ببقع صفراء دائرية في الرومي = الرأس الأسود\n• رواسب بيضاء طباشيرية على القلب والكبد والكلى = نقرس حشوي\n• كبد شاحب دهني مع نزيف تحت الجلد = أفلاتوكسين أو كبد دهني\n• كلى منتفخة وشاحبة مع رواسب = IB كلوي أو نقرس أو سموم\n\nقواعد مهمة:\n• آفة واحدة مش تشخيص — الصورة الكاملة (العمر، الأعراض، التحصين، الأدوية) هي اللي بتدي تشخيصاً قابلاً للتصديق\n• التأكيد النهائي بالمعمل (PCR، زرع وحساسية، سيرولوجي، فحص نسيجي)\n• عينات الزرع البكتيري تتبعت مبرّدة (2-8°م) في خلال 24 ساعة ومتتجمّدش، والعينات النسيجية في فورمالين 10%، وبالنسبة لعينات الـ PCR اسأل المعمل عن طريقة الحفظ المناسبة"
        }
