          "content": "بتبص على رقمين مش رقم واحد:\n\n1) متوسط العيار (Mean Titer): مستوى المناعة العام\n• نيوكاسل HI: حوالي 4 log2 يُعتبر الحد الأدنى للحماية في التسمين، والمطلوب أعلى (حوالي 6-8 log2) في البياض والأمهات بعد اللقاح المقتول — حدود التفسير بتختلف حسب الاختبار والمعمل، فراجع أخصائي المعمل\n\n2) التجانس (CV%): مدى تباين النتائج بين الطيور\n• CV أقل من 30%: تجانس جيد (التطبيق كان متساوي)\n• CV فوق 50%: ثغرة في التطبيق (جرعة غير متساوية في الشرب أو الرش، أو طيور فاتها اللقاح أو الحقن)\n\nمواقف تفسيرية شائعة:\n• عيار عالي جداً قبل أي تحصين = مناعة أمومية أو عدوى ميدانية — لازم تفسيره مع التاريخ المرضي\n• عيار منخفض + CV عالي بعد لقاح شرب = غالباً مشكلة طريقة تطبيق (مياه، كلور، توقيت)\n• عيار منخفض + CV عالي بعد لقاح مقتول = حقن غير منتظم\n• عيار منخفض بتجانس واضح = غالباً مشكلة في اللقاح نفسه (تخزين أو جودة) أو كبت مناعي — راجع المورد وجودة العلف\n• عيار مرتفع في قطيع مش متحصن ضد المرض ده = تعرّض لفيروس الحقل، وده مؤشر خطر\n\nالقرار: النتيجة لازم تتحول لإجراء (تعديل ميعاد التحصين، تغيير طريقة التطبيق، إعادة التحصين، تغيير المورد) مش مجرد ورقة في الملف."
