          "title": "المواد الماصة والتعامل مع الحالة",
          "content": "المواد الماصة للسموم (Binders):\n• الطين (بنتونيت وHSCAS) فعّال عادةً ضد الأفلاتوكسين، وأقل فعالية ضد أوكراتوكسين وT-2 وDON\n• جدر الخميرة والإنزيمات والمكملات متعددة المكونات ممكن تساعد في سموم تانية\n• الأدلة بتتفاوت بين المنتجات: اطلب بيانات تجارب، واستخدم الجرعة المكتوبة على النشرة\n• المادة الماصة بتقلل الأثر لكنها مش بتحوّل علف شديد التلوث لعلف آمن\n\nلو اشتبهت في تسمم فطري:\n1. غيّر العلف فوراً واحتفظ بعينة للتحليل\n2. دعم الكبد والمناعة بإشراف أخصائي التغذية أو البيطري (فيتامينات، مواد داعمة)\n3. فيتامين E وسيلينيوم وC وتحسين البيئة\n4. راقب العدوى الثانوية (إشريكية، كوكسيديا) وعالجها بتشخيص\n5. التعافي عادةً بياخد أسبوع لأسبوعين أو أكتر بعد إزالة المصدر حسب شدة الإصابة\n\nسجّل رقم الشحنة والمورد، وبلّغ المورد وجهة الرقابة لو التلوث مؤكد."
